function reviveDates(modelName: string, row: Record<string, unknown>) {
  const dateFields = new Set<string>((SNAPSHOT.dateFieldsByModel as Record<string, readonly string[]>)[modelName] || []);
  return Object.fromEntries(
    Object.entries(row).map(([key, value]) => [
      key,
      dateFields.has(key) && typeof value === 'string' ? new Date(value) : value,
    ]),
  );
}

function withoutId(row: Record<string, unknown>) {
  const { id: _id, ...rest } = row;
  return rest;
}

function buildInitialCreateRow(modelName: string, row: Record<string, unknown>) {
  const optionalRelationScalars = new Set<string>((SNAPSHOT.optionalRelationScalarsByModel as Record<string, readonly string[]>)[modelName] || []);
  return Object.fromEntries(
    Object.entries(row).map(([key, value]) => [key, optionalRelationScalars.has(key) ? null : value]),
  );
}

function getDelegate(modelName: string) {
  const delegateName = (SNAPSHOT.delegateByModel as Record<string, string>)[modelName];
  const delegate = (prisma as any)[delegateName];
  if (!delegate?.upsert || !delegate?.update) {
    throw new Error(`Missing Prisma delegate for ${modelName} (${delegateName})`);
  }
  return delegate;
}

async function upsertInitialRows(modelName: string, rows: readonly Record<string, unknown>[]) {
  const delegate = getDelegate(modelName);
  for (const rawRow of rows) {
    const row = reviveDates(modelName, rawRow);
    const createRow = buildInitialCreateRow(modelName, row);
    await delegate.upsert({
      where: { id: row.id },
      create: createRow,
      update: withoutId(createRow),
    });
  }
  console.log(`[seed:full-production-snapshot] initial ${modelName}: ${rows.length} rows`);
}

async function updateFinalRows(modelName: string, rows: readonly Record<string, unknown>[]) {
  const delegate = getDelegate(modelName);
  for (const rawRow of rows) {
    const row = reviveDates(modelName, rawRow);
    await delegate.update({
      where: { id: row.id },
      data: withoutId(row),
    });
  }
  console.log(`[seed:full-production-snapshot] final ${modelName}: ${rows.length} rows`);
}

async function main() {
  console.log('[seed:full-production-snapshot] Starting restore from seed-full-production-snapshot-2026-08-15.ts');
  console.log('[seed:full-production-snapshot] Snapshot generated at:', SNAPSHOT.generatedAt);

  for (const modelName of SNAPSHOT.modelOrder) {
    await upsertInitialRows(modelName, (SNAPSHOT.models as any)[modelName] || []);
  }

  // Restore optional relation scalars after all records exist. This preserves circular/optional relationships.
  for (const modelName of SNAPSHOT.modelOrder) {
    await updateFinalRows(modelName, (SNAPSHOT.models as any)[modelName] || []);
  }

  console.log('[seed:full-production-snapshot] Completed restore.');
}

main()
  .catch((error) => {
    console.error('[seed:full-production-snapshot] Failed:', error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
